    count = 0
    # f(x, y) is a bijection from Z^2 to Z
    # We want to count how many (x, y) with 0 <= x, y < limit have f(x, y) odd.
    for x in range(limit):
        for y in range(limit):
            d = x + y
            if f_type == 'x':
                val = d * (d + 1) // 2 + x
            else:
                val = d * (d + 1) // 2 + y
            if val % 2 == 1:
                count += 1
    return count

