def check_image(f_type, limit):
    image = set()
    for x in range(limit):
        for y in range(limit):
            d = x + y
            if f_type == 'x':
                val = d * (d + 1) // 2 + x
            else:
                val = d * (d + 1) // 2 + y
            image.add(val)

    missing = []
    for k in range(limit * limit):
        if k not in image:
            missing.append(k)
    return missing

