import itertools

def is_valid(f, limit):
    # f is a bijection from {0,1,2}^2 to {0,1,2,3,4,5}
    # Condition: f(x1, y1) > f(x2, y2) => f(x1+1, y1) > f(x2+1, y2) and f(x1, y1+1) > f(x2, y2+1)
    # We need to check this for all x1, y1, x2, y2 such that x1+1, y1, x1, y1+1, x2+1, y2, x2, y2+1 are in {0,1,2}^2
    points = [(x, y) for x in range(limit) for y in range(limit)]
    for p1 in points:
        for p2 in points:
            if f[p1] > f[p2]:
                # Check x+1
                p1_x = (p1[0] + 1, p1[1])
                p2_x = (p2[0] + 1, p2[1])
                if p1_x[0] < limit and p2_x[0] < limit:
                    if not (f[p1_x] > f[p2_x]):
                        return False
                # Check y+1
                p1_y = (p1[0], p1[1] + 1)
                p2_y = (p2[0], p2[1] + 1)
                if p1_y[1] < limit and p2_y[1] < limit:
                    if not (f[p1_y] > f[p2_y]):
                        return False
    return True

def solve():
    limit = 3
    points = [(x, y) for x in range(limit) for y in range(limit)]
    values = list(range(limit * limit))
    valid_f = []
    for p in itertools.permutations(values):
        f = {points[i]: p[i] for i in range(len(points))}
        if is_valid(f, limit):
            valid_f.append(f)
    return valid_f

valid_f = solve()
print(f"Number of valid f: {len(valid_f)}")
for f in valid_f[:5]:
